from html import escape
from motion_components import product_drawing

def technical_explorer(products):
 p=products[0]
 tabs=''.join(f'<button role="tab" id="product-tab-{i}" aria-selected="{str(i==0).lower()}" aria-controls="product-preview" tabindex="{0 if i==0 else -1}" data-product="{i}"><span>{escape(p["name"])}</span></button>' for i,p in enumerate(products))
 templates=''.join(f'<template id="product-sketch-{i}">{product_drawing(i)}</template>' for i in range(len(products)))
 return '''<section class="product-universe technical-universe" id="product-universe"><div class="section-heading split"><div><p class="eyebrow">02 / PRODUCT UNIVERSE</p><h2>SPECIFIED WITH PURPOSE.<br>CONNECTED WITH PRECISION.</h2></div><p>Explore the components behind critical systems.<br>From material selection to a project-ready enquiry.</p></div><div class="technical-console"><div class="console-top"><span>UNITED PIPING / PRODUCT EXPLORER</span><span>DRAWING & MATERIAL REFERENCE</span></div><div class="product-explorer"><div class="product-tabs" role="tablist" aria-label="Product categories" aria-orientation="vertical">'''+tabs+'''</div><div id="product-preview" role="tabpanel" aria-labelledby="product-tab-0"><div class="explorer-stage"><div class="explorer-drawing">'''+product_drawing(0)+'''</div></div><div class="explorer-specs"><h3>Pipes</h3><p>Seamless and welded pipes across published industrial material families.</p><a class="text-link" href="/products/pipes/">Explore pipes</a></div></div></div><div class="console-bottom"><span>SCHEMATIC VIEWS · NOT TO SCALE</span><a href="/products/">VIEW COMPLETE PORTFOLIO</a><span>SPECIFICATION SUBJECT TO REVIEW</span></div></div>'''+templates+'''</section>'''

def integrated_services(services):
    return '''<section class="integrated-services" id="beyond-supply"><div class="section-heading split"><div><p class="eyebrow">03 / BEYOND SUPPLY</p><h2>THE MATERIAL IS ONLY<br>THE BEGINNING.</h2></div><p>One coordinated approach to preparation,<br>verification, documentation, and delivery.</p></div><div class="services-editorial"><figure class="inspection-photo"><img src="/assets/inspection-engineer.jpg" width="2048" height="1365" loading="lazy" alt="Engineer using a vernier caliper to inspect a large steel pipe"><div class="photo-crosshair" aria-hidden="true"></div><figcaption><span>TECHNICAL OVERSIGHT</span><span>Inspection reference image</span></figcaption></figure><div class="service-sequence"><p class="service-intro">From your first specification to the final documentation package, our services connect each stage of industrial procurement.</p>'''+''.join(f'<details class="service-step" {"open" if i==1 else ""}><summary><span class="service-node" aria-hidden="true"></span><span>{escape(s["name"])}</span><b aria-hidden="true">+</b></summary><div><p>{escape(s["description"])}</p><a class="text-link" href="/services/{s["slug"]}/">Explore {escape(s["name"].lower())}</a></div></details>' for i,s in enumerate(services))+'''</div></div><div class="service-footer"><span>ALIGNED TO YOUR PROJECT REQUIREMENTS</span><a class="button" href="/request-a-quote/">Discuss your project</a></div></section>'''

def drawing_library():
 return '''<section class="drawing-library"><div class="drawing-library-copy"><p class="eyebrow">THE ENGINEERING REFERENCE</p><h2>EVERY CONNECTION<br>STARTS ON PAPER.</h2><p>From orthographic views to component geometry, drawings make complex requirements clear.</p><p class="small-note">Supplied flange drawing for visual reference only. Its dimensions, pressure class, and applicability have not been verified for our products.</p><button type="button" class="button secondary" data-open-drawing>Inspect the drawing</button><a class="text-link" href="/assets/flange-drawing-reference.jpg" download>Download supplied reference · JPG</a></div><button type="button" class="reference-sheet" data-open-drawing aria-label="Open supplied flange reference drawing"><img src="/assets/flange-drawing-reference.jpg" width="2059" height="1456" loading="lazy" alt="Supplied multi-view flange reference drawing with front and isometric views"><span>OPEN DRAWING SHEET</span></button></section><dialog class="drawing-dialog" aria-labelledby="drawing-dialog-title"><div><h2 id="drawing-dialog-title">Flange connection / supplied reference</h2><button type="button" data-close-drawing aria-label="Close reference drawing">Close ×</button></div><p>Reference only — not an approved product drawing. Verify all dimensions and standards before use.</p><img src="/assets/flange-drawing-reference.jpg" width="2059" height="1456" alt="Enlarged supplied flange reference drawing"><a href="/assets/flange-drawing-reference.jpg" download>Download reference JPG</a></dialog>'''

def product_documents(p):
 docs=p.get('technicalDocuments',[])
 return '<section class="product-documents"><div><p class="eyebrow">TECHNICAL RESOURCE DESK</p><h2>REFERENCE. REVIEW. SPECIFY.</h2><p>Keep the published starting information with your project enquiry.</p></div><div class="document-links"><a href="/documents/'+p['id']+'-reference.csv" download><span>Published specification summary</span><small>CSV · Brief-based reference · Engineering review required</small></a>'+''.join('<a href="'+escape(d['url'])+'" download><span>'+escape(d['name'])+'</span><small>'+escape(d.get('status','Reference only'))+'</small></a>' for d in docs)+'<p class="small-note">Manufacturer datasheets and certified drawings are supplied when available against the selected product and project requirements.</p></div></section>'
